pub(super) fn tiers_text(tiers: &[DisplayTierInspection]) -> String {
    if tiers.is_empty() {
        return "[]".to_string();
    }

    let entries = tiers
        .iter()
        .map(|tier| format!("{}@{}", tier.name, format_number(tier.min_size)))
        .collect::<Vec<_>>()
        .join(", ");
    format!("[{entries}]")
}
